import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative squared deviation of each machine load from the current mean load (pull the laggards up)."""
    m = len(loads)
    mean_load = loads.mean()
    # scale by mean job size seen so far (or the job itself early on)
    if past_jobs.size > 0:
        scale = past_jobs.mean()
    else:
        scale = job
    scale = max(scale, 1e-9)
    dev = (loads - mean_load) / scale
    return -np.tanh(dev * dev)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative current load of each machine, normalised by the mean load after placing the arriving job."""
    m = loads.shape[0]
    scale = (loads.sum() + job) / m + 1e-9
    return -(loads / scale)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """-1 for machines whose load is strictly above the median load, 0 otherwise."""
    med = float(np.median(loads))
    return -(loads > med).astype(float)

