import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative rank of each machine's load among all loads (dense rank from lowest=0), normalised by m-1: a coarse ordinal balance signal invariant to load magnitude scale."""
    m = len(loads)
    order = np.argsort(np.argsort(loads))  # 0 for the smallest load
    return -(order.astype(float)) / max(m - 1, 1)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Col0: negative load deviation over load spread+job; Col1: in the tail (jobs_left<m), negative distance of load+job to projected final mean, scaled by job."""
    m = loads.shape[0]
    spread = loads.max() - loads.min()
    col0 = -(loads - loads.mean()) / (spread + job + 1e-9)

    if jobs_left < m:
        mean_past = past_jobs.mean() if past_jobs.size else job
        target = (loads.sum() + job + mean_past * jobs_left) / m
        col1 = -np.abs(loads + job - target) / (job + 1e-9)
    else:
        col1 = np.zeros(m)

    return np.stack([col0, col1], axis=1)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Col0: negative load deviation normalised by load spread plus job; Col1: for tiny jobs, negative absolute deviation from mean load normalised by std plus job, else 0."""
    loads = np.asarray(loads, dtype=float)
    mean = loads.mean()
    spread = loads.max() - loads.min()
    col0 = -(loads - mean) / (spread + job + 1e-9)

    if past_jobs.size > 0 and job < 0.1 * past_jobs.mean():
        col1 = -np.abs(loads - mean) / (loads.std() + job + 1e-9)
    else:
        col1 = np.zeros_like(loads)

    return np.stack([col0, col1], axis=1)
